    _, j = _js_parse_ignored_value(text, j, depth, state)
    j = _js_skip_ws(text, j)
    if j >= n or text[j] != ",":
        raise _JSExprFail("F538 thisArg without argsList")
    j = _js_skip_ws(text, j + 1)
