    j = _js_skip_ws(text, j)
    if j >= n or text[j] != ",":
        raise _JSExprFail("F556 bound target without thisArg")
    j = _js_skip_ws(text, j + 1)
    _, j = _js_parse_ignored_value(text, j, depth, state)
    j = _js_skip_ws(text, j)
    if j >= n or text[j] != ",":
        raise _JSExprFail("F556 thisArg without argsList")
    j = _js_skip_ws(text, j + 1)
