def _js_parse_projection_return(text, i, p):
    """Parse `return P[N];` at text[i] (F517 entries projection).

    *p* is the expected parameter name. Returns (index, next_index)
    with index in {0, 1}; anything else (other idents, other
    indices, missing semicolon) fails closed. Never evals.
    """
    j = _js_skip_ws(text, i)
    rk = _js_match_kw(text, j, "return")
    if rk is None:
        raise _JSExprFail("projection not return p[N]")
    j = _js_skip_ws(text, rk)
    q, j = _js_parse_ident(text, j)
    if q != p:
        raise _JSExprFail("projection not return p[N]")
    br = _js_parse_bracket_index(text[j:])
    if br is None or br[0] not in (0, 1):
        raise _JSExprFail("projection index not 0/1")
    idx, consumed = br
    j = _js_skip_ws(text, j + consumed)
    j = _js_expect(text, j, ";")
    return idx, j


def _js_parse_entries_destructure_projection(text, i):
    """Parse a destructured entries-projection .map callback at text[i]
    (F583).

    Returns ("keys"|"vals", next_index). Recognized (node-verified,
    v24.20.0): `([p0])=>p0`, `([p0,p1])=>p0`, `([p0,p1])=>p1`, and the
    block-body (`=>{return p0;}`) and `function([p0]){return p0;}`
    twins. The parameter is a 1- or 2-element array pattern over the
    [k, v] pair; the body must return one of the bound names --
    returning the first binds element 0 (the key), the second element
    1 (the value). Duplicate binding names (`([k,k])=>k` -- the
    engine binds the second, i.e. element 1) fail closed rather than
    mis-project; 3+ names, elisions (`([,v])`), rest elements, and
    default values fail closed (documented boundaries). Never evals.
    """
    n = len(text)
    j = _js_skip_ws(text, i)
    _fn = False
    if text.startswith("function", j):
        k = j + len("function")
        if k < n and text[k] in _JS_IDENT_CONT:
            raise _JSExprFail("bad destructure projection")
        j = _js_skip_ws(text, k)
        _fn = True
    j = _js_expect(text, j, "(")
    j = _js_skip_ws(text, j)
    if j >= n or text[j] != "[":
        raise _JSExprFail("not a destructure projection")
    j = _js_skip_ws(text, j + 1)
    p0, j = _js_parse_ident(text, j)
    j = _js_skip_ws(text, j)
    _names = [p0]
    if j < n and text[j] == ",":
        j = _js_skip_ws(text, j + 1)
        p1, j = _js_parse_ident(text, j)
        _names.append(p1)
        j = _js_skip_ws(text, j)
        if j < n and text[j] == ",":
            raise _JSExprFail("destructure projection arity")
    if len(set(_names)) != len(_names):
        # ([k,k])=>k -- the engine binds the SECOND k (element 1);
        # fail closed rather than mis-project.
        raise _JSExprFail("destructure projection duplicate name")
    j = _js_expect(text, j, "]")
    j = _js_expect(text, j, ")")
    j = _js_skip_ws(text, j)
    if _fn:
        j = _js_expect(text, j, "{")
        _rk = _js_match_kw(text, _js_skip_ws(text, j), "return")
        if _rk is None:
            raise _JSExprFail("bad destructure projection")
        j = _js_skip_ws(text, _rk)
        q, j = _js_parse_ident(text, j)
        j = _js_skip_ws(text, j)
        j = _js_expect(text, j, ";")
        j = _js_expect(text, j, "}")
    else:
        if not text.startswith("=>", j):
            raise _JSExprFail("bad destructure projection")
        j = _js_skip_ws(text, j + 2)
        if j < n and text[j] == "{":
            j = _js_skip_ws(text, j + 1)
            _rk = _js_match_kw(text, j, "return")
            if _rk is None:
                raise _JSExprFail("bad destructure projection")
            j = _js_skip_ws(text, _rk)
            q, j = _js_parse_ident(text, j)
            j = _js_skip_ws(text, j)
            j = _js_expect(text, j, ";")
            j = _js_expect(text, j, "}")
        else:
            q, j = _js_parse_ident(text, j)
    if q == _names[0]:
        return "keys", j
    if len(_names) == 2 and q == _names[1]:
        return "vals", j
    raise _JSExprFail("destructure projection not a bound name")


def _js_parse_entries_projection(text, i):
    """Parse an entries-projection .map callback at text[i] (F517).

    Returns ("keys"|"vals", next_index). Recognized (node-verified,
    v24.20.0): `p=>p[0|1]`, `(p)=>p[0|1]`, `p=>{return p[0|1];}`,
    `function(p){return p[0|1];}`. The callback must project its
    single pair parameter's element 0 (the key) or 1 (the value);
    anything else fails closed (notably `.map(p=>p)` -- the engine
    keeps pairs, which the decoder does not model; failing closed
    rather than mis-decoding). Never evals.
    """
    n = len(text)
    j = _js_skip_ws(text, i)
    # F583: destructured pair param -- tried before the plain-param
    # forms (disjoint: a plain param never starts with `[`, and
    # `function([` never reaches the plain function branch, whose
    # ident parse would fail closed on `[` anyway).
    _fj = j
    if text.startswith("function", _fj):
        _fk = _fj + len("function")
        if not (_fk < n and text[_fk] in _JS_IDENT_CONT):
            _fj = _js_skip_ws(text, _fk)
    if _fj < n and text[_fj] == "(":
        _fq = _js_skip_ws(text, _fj + 1)
        if _fq < n and text[_fq] == "[":
            return _js_parse_entries_destructure_projection(text, i)
    if text.startswith("function", j):
        k = j + len("function")
        if k < n and text[k] in _JS_IDENT_CONT:
            raise _JSExprFail("bad entries projection")
        k = _js_expect(text, k, "(")
        p, k = _js_parse_ident(text, _js_skip_ws(text, k))
        k = _js_expect(text, k, ")")
        k = _js_expect(text, k, "{")
        idx, k = _js_parse_projection_return(text, k, p)
        k = _js_expect(text, k, "}")
        return ("keys" if idx == 0 else "vals"), k
    if j < n and text[j] == "(":
        p, j = _js_parse_ident(text, _js_skip_ws(text, j + 1))
        j = _js_expect(text, j, ")")
    else:
        p, j = _js_parse_ident(text, j)
    j = _js_skip_ws(text, j)
    if not text.startswith("=>", j):
        raise _JSExprFail("bad entries projection")
    j = _js_skip_ws(text, j + 2)
    if j < n and text[j] == "{":
        # Block body: {return p[N];} -- single return, no other
        # statements (the F448 discipline).
        j = _js_expect(text, j, "{")
        idx, j = _js_parse_projection_return(text, j, p)
        j = _js_expect(text, j, "}")
        return ("keys" if idx == 0 else "vals"), j
    q, j = _js_parse_ident(text, j)
    if q != p:
        raise _JSExprFail("entries projection not p[N]")
    br = _js_parse_bracket_index(text[j:])
    if br is None or br[0] not in (0, 1):
        raise _JSExprFail("entries projection index not 0/1")
    idx, consumed = br
    return ("keys" if idx == 0 else "vals"), j + consumed


def _js_parse_f573_entries_literal(text, i, depth, state):
    """Parse `Object.entries(OBJLIT)` / `Object['entries'](OBJLIT)` bare
    (F573).

    The F517 parser (`_js_parse_object_entries`) requires a `.map`
    projection after the call; a bare `Object.entries(OBJLIT)` is a
    different production -- an array of `[k, v]` pairs the composer
    can thread into index reads (`[0][1]`), member reads (`.y`), and
    join chains via the normal postfix grammar. Node-exact
    (v24.20.0): the literal is parsed by `_js_parse_f535_object`
    (string literals, canonical ints, nested objects; getters
    evaluated at parse time exactly like F535 -- the engine invokes
    them during enumeration) and keys are reordered to engine
    enumeration order (integer-index keys ascending numerically
    first, then string keys in insertion order; duplicates keep
    first-insertion position with the later value -- both match the
    engine and the F535 dict behavior).

    Returns (value, next_index) via _js_parse_postfix over the
    `_JSArr` of `_JSArr([k, v])` pairs, or None when text[i] is not
    this shape (the caller falls through to F517's parser). When the
    call IS followed by `.map`, this parser defers (returns None) so
    F517 keeps its mandatory-projection grammar unchanged. Once the
    `entries` member commits the parse, malformed shapes fail closed
    via _JSExprFail.

    Bounds (all fail closed -- rejected, never mis-decoded):
    - a non-`{` argument (variables, calls, wrappers -- F517's
      enumeration sources stay F517's);
    - symbol keys are SKIPPED (the engine excludes them from
      entries() -- node v24.20.0 verified);
    - octal-looking digit keys (`01` -- the engine reads an octal
      literal, the static key text would mis-order);
    - extra call arguments (F517 parity -- its parser raises
      identically on the `.map` form).
    Never evals.
    """
    n = len(text)
    if i > 0 and text[i - 1] in _JS_IDENT_CONT:
        return None
    if not text.startswith("Object", i):
        return None
    j = i + len("Object")
    if j < n and text[j] in _JS_IDENT_CONT:
        return None  # Objectx -- fall through
    j = _js_skip_ws(text, j)
    if j < n and text[j] == "[":
        # F480: Object['entries'] -- bracket-string member access,
        # engine-identical to the dot form (node v24.20.0 verified).
        _mname, j = _js_parse_bracket_member(text, j)
        if _mname != "entries":
            return None  # not entries -- fall through
    elif j < n and text[j] == ".":
        j = _js_skip_ws(text, j + 1)
        m = _js_match_kw(text, j, "entries")
        if m is None:
            return None  # not entries -- fall through
        j = m
    else:
        return None
    # The `entries` member commits the parse.
    j = _js_skip_ws(text, j)
    if j >= n or text[j] != "(":
        raise _JSExprFail("F573 entries without paren")
    j = _js_skip_ws(text, j + 1)
    if j >= n or text[j] != "{":
        # Not a plain object literal -- F517's enumeration sources
        # (wrappers, reduce-rebuild) stay F517's.
        return None
    props, j = _js_parse_f535_object(text, j, depth, state)
    j = _js_skip_ws(text, j)
    if j >= n or text[j] != ")":
        raise _JSExprFail("F573 entries with extra args")
    j += 1
    # F517 owns the `.map` projection form -- defer so its
    # mandatory-projection grammar is unchanged.
    q = _js_skip_ws(text, j)
    if q < n and text[q] == ".":
        if _js_match_kw(text, _js_skip_ws(text, q + 1), "map") is not None:
            return None
    # Engine enumeration order via the F517 helper (node v24.20.0
    # verified): integer indices ascending first, then string keys
    # in insertion order. Symbol keys fail closed (documented).
    key_order = []
    int_poss = []
    str_poss = []
    for key in props:
        if not isinstance(key, str):
            # Symbol keys: the engine EXCLUDES them from
            # Object.entries() (node v24.20.0 verified), so the
            # model skips them rather than fail closed.
            continue
        if (len(key) > 1 and key[0] == "0"
                and all("0" <= c <= "9" for c in key)):
            # Octal-looking digit key: the engine reads an octal
            # literal, so the static key text would mis-order.
            raise _JSExprFail("F573 octal-looking key fails closed")
        pos = len(key_order)
        key_order.append(key)
        if _js_is_integer_index_key(key):
            int_poss.append((int(key), pos))
        else:
            str_poss.append(pos)
    ordered = _js_order_object_keys(key_order, int_poss, str_poss)
    pairs = _JSArr([_JSArr([k, props[k]]) for k in ordered])
    state["ops"] += 1  # the entries call is obfuscation-shaped
    return _js_parse_postfix(text, j, pairs, depth, state)


